// readLog reads the log until two consecutive reads are byte-identical and
// every complete line passes its checksum. Reads may be transiently corrupted,
// so a single read is never trusted on its own.
func readLog(path string) (map[string]string, int, int, error) {
	var prev []byte
	havePrev := false
	for attempt := 0; attempt < 200; attempt++ {
		data, err := os.ReadFile(path)
		if err != nil && !os.IsNotExist(err) {
			return nil, 0, 0, err
		}
		values, complete, ok := parse(data)
		if ok && havePrev && bytes.Equal(prev, data) {
			return values, complete, len(data), nil
		}
		prev, havePrev = data, true
	}
	return nil, 0, 0, fmt.Errorf("kv.log: could not obtain a verified read of %s", path)
}

// line format: "%08x payload\n" where the hex is CRC32 (IEEE) of payload.
func parse(data []byte) (map[string]string, int, bool) {
	values := map[string]string{}
	complete := 0
	for {
		i := bytes.IndexByte(data[complete:], '\n')
		if i < 0 {
			return values, complete, true
		}
		line := string(data[complete : complete+i])
		complete += i + 1
		if len(line) < 9 || line[8] != ' ' {
			return values, complete, false
		}
		sum, err := strconv.ParseUint(line[:8], 16, 32)
		if err != nil {
			return values, complete, false
		}
		payload := line[9:]
		if uint32(sum) != crc32.ChecksumIEEE([]byte(payload)) {
			return values, complete, false
		}
		if k, v, ok := strings.Cut(payload, "="); ok {
			values[k] = v
		}
	}
}

